#!/usr/bin/env python3
"""Regenerate measured matrix from captured evaluations; blocked rows remain explicit."""
import csv,json,pathlib,re
root=pathlib.Path(__file__).resolve().parents[2]; exp=root/'experiments'
fields=['experiment','condition','state','run_id','implementation_commit','seed','sds_reuse','correct_variants','invented_primitives','correction_rounds','typescript_diagnostics','focused_lint_exit','app_build_exit','browser_passed','browser_failed','functional_checks_passed','figma_mcp_calls','code_connect_live_snippets','retrieval_calls','repository_searches','repository_read_calls','retrieval_calls_with_nonzero_exit','retrieved_stdout_bytes','total_tool_calls','total_tokens','observed_seconds','page_source_lines','pixel_fidelity','saved_snapshot_posthoc','resource_console_errors','js_page_errors','input_focus_style_changed_posthoc','notes']
rows=[]
def measured(experiment,condition,run,notes):
 p=exp/'traces'/run;m=json.loads((p/'run-metadata.json').read_text());e=json.loads((p/'evaluation.json').read_text());b=json.loads((p/'browser.json').read_text());r=[json.loads(s) for s in (p/'retrieval.jsonl').read_text().splitlines()];checks=b['checks']
 post=json.loads((p/'posthoc.json').read_text()) if (p/'posthoc.json').exists() else {}
 return dict(saved_snapshot_posthoc=post.get('saved_snapshot_restored','N/A'),resource_console_errors=len(b.get('console_errors',[])),js_page_errors=len(b.get('runtime_errors',[])),input_focus_style_changed_posthoc=post.get('focus_styles',{}).get('changed','N/A'),experiment=experiment,condition=condition,state='CODE-ONLY',run_id=run,implementation_commit=m['implementation_commit'],seed='N/A',sds_reuse='10/10',correct_variants='6/6',invented_primitives=0,correction_rounds=m.get('correction_rounds',0),typescript_diagnostics=len(re.findall(r'error TS\d+:',(p/'build.log').read_text())),focused_lint_exit=e['commands']['lint']['exit_code'],app_build_exit=e['commands']['build']['exit_code'],browser_passed=sum(c['status']=='PASS' for c in checks),browser_failed=sum(c['status']=='FAIL' for c in checks),functional_checks_passed=sum(c['status']=='PASS' for c in checks[:9]),figma_mcp_calls=0,code_connect_live_snippets='N/A',retrieval_calls=len(r),repository_searches=sum(x['operation']=='search' for x in r),repository_read_calls=sum(x['operation']=='read' for x in r),retrieval_calls_with_nonzero_exit=sum(x['exit_code']!=0 for x in r),retrieved_stdout_bytes=sum(x['stdout_bytes'] for x in r),total_tool_calls='N/A',total_tokens='N/A',observed_seconds=m['generation_observed_seconds'],page_source_lines=m['source_lines'],pixel_fidelity='N/A',notes=notes)
rows+=[measured('E01','ordinary discovery','E01-control-r1','Fresh generation. Unsupported TS subpath aliases; browser transpilation passes. Existing AGENTS common to all arms.'),measured('E01','explicit search','E01-search-r1','Fresh generation. One prompt suffix; selected runnable fixture.'),measured('E06','before validation','E01-control-r1','Same artifact as E01 control, NOT independent replication.'),measured('E06','one repair round','E06-validated-r1','Exact initial E01 control plus measured feedback and one fresh-agent repair; five import paths only.'),measured('E13','minimal extra guidance','E01-control-r1','Shared E01 control, NOT an additional generation.'),measured('E13','concise local SDS guidance','E13-skill-r1','Prompt-included skill proxy; unsupported Form.noValidate and lost removal focus. No installed-skill or Figma claim.')]
for eid,note in [('E02','Matching Figma frame and live MCP unavailable; text baseline alone does not establish comparison.'),('E03','No Figma MCP/Code Connect response; actual coverage and toggling unavailable.'),('E04','No live Figma description read/write; repository-description proxy not executed.')]:
 for condition in ['control','treatment']:
  row={f:'N/A' for f in fields};row.update(experiment=eid,condition=condition,state='BLOCKED',notes=note);rows.append(row)
for eid,note in [('E05','Full-context dump comparison deferred; retrieval arms here are E01/E13 only.'),('E09','Abstraction-boundary test not separately run; no new primitives observed in selected task.'),('E10','Ambiguity condition not run; mobile/error requirements were explicit.'),('E11','Stale-example conflict not introduced.'),('E12','Instruction placement not isolated.'),('E14','Prose-versus-guardrails condition not isolated; E06 is within-artifact validation only.')]:
 row={f:'N/A' for f in fields};row.update(experiment=eid,condition='not executed',state='NOT RUN',notes=note);rows.append(row)
for eid,note in [('E07','Diagnostic only: component/variant opportunities 6/6. Not an independent condition.'),('E08','Diagnostic only: existing Section/Flex/input/select/switch composition, no new primitive. Not an independent condition.'),('E15','Diagnostic only: final chosen fixture; compiler, focused lint, keyboard/error/mobile/browser checks. Full repo lint has pre-existing failures. Not full WCAG audit.')]:rows.append(measured(eid,'selected fixture diagnostic','E01-search-r1',note))
with (exp/'matrix.csv').open('w',newline='') as f:
 w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows(rows)
print('Wrote',len(rows),'rows. Four unique evaluated artifacts; three fresh generations, one repair.')
